// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport timber.log.Timberimport com.roshan.persona.vision.core.ConfidenceTierimport com.roshan.persona.vision.core.ConfidenceThresholdsimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.document.BusinessCardParserimport com.roshan.persona.vision.document.GovernmentIdParserimport com.roshan.persona.vision.document.HandwrittenNoteParserimport com.roshan.persona.vision.document.InvoiceParserimport com.roshan.persona.vision.document.ReceiptParserimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContextimport java.security.MessageDigest/** * NOUS — OCR Engine (Module 6 v4 — Step 6.2, CRITICAL). * * The main OCR orchestrator — runs the full pipeline: * * ``` * 1. SHA-256 cache lookup (skip if cached) * 2. Image Enhancement Pipeline (Dual-Window LCE for shadow removal) * 3. ML Kit Text Recognition (Latin + Devanagari + 60 scripts) * 4. Field Extraction (regex: phone, email, PAN, Aadhaar, GSTIN, IFSC, UPI, money, date) * 5. Document Type Detection (receipt, prescription, business card, ID, etc.) * 6. Structured Document Parsing (Receipt, Prescription, BusinessCard, GovernmentId) * 7. Cache result (SHA-256 keyed, 7-day TTL) * ``` * * ## Performance (per strategy v4) * *  - Typical receipt (720p, no shadow): 300ms (50ms enhance + 200ms ML Kit + 50ms extract) *  - Shadowed receipt (720p, with Dual-Window LCE): 495ms (195ms enhance + 200ms ML Kit + 100ms extract) *  - Full A4 page (720p, dense text): 1.5s (enhance + 1s ML Kit + extract) *  - All within v4 budgets (800ms receipt, 3s A4). * * ## Confidence Thresholds (per strategy v4 §"Issue 1") * *  - OCR has no minimum threshold — raw text is always returned. *  - But [OcrResult.overallConfidence] drives the [ConfidenceTier]: *    - HIGH (≥0.85): clean scan, speak full text via TTS *    - MEDIUM (0.65-0.85): minor noise, speak text but suggest retake *    - LOW (0.35-0.65): poor scan, don't speak — suggest retake *    - REJECT (<0.35): no usable text — require retake * * ## Error Recovery (per strategy v4 §"Issue 3") * * | Error | Recovery | User Feedback | * |-------|----------|---------------| * | ML Kit crashes | Retry with enhanced preprocessing (denoise + contrast); if still fails → suggest retake | "I couldn't read this clearly. Please hold steady and try again." | * | Enhancement throws | Skip enhancement, try ML Kit on raw image | (transparent to user) | * | Empty OCR result | Return REJECTED tiered result | "I can't read anything on this. Try a clearer photo." | * | Timeout (>5s) | Cancel + return REJECTED | "OCR timed out. Try again." | * * ## Testability * * The actual ML Kit inference is delegated to [OcrRecognizer] interface. * Production: [MlKitOcrRecognizer] wraps `com.google.mlkit:text-recognition`. * Tests: [FakeOcrRecognizer] returns canned OCR output. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.2: OcrEngine v4</a> */class OcrEngine(    private val recognizer: OcrRecognizer,    private val enhancementPipeline: ImageEnhancementPipeline,    private val fieldExtractor: OcrFieldExtractor,    private val documentFormatDetector: DocumentFormatDetector,    private val structuredDocParser: StructuredDocumentParser,    private val cache: OcrCache,    private val dispatcher: CoroutineDispatcher,) {    /**     * Recognize text in [imageBytes] + extract structured fields.     *     * @param imageBytes the raw input image (JPEG/PNG).     * @param options OCR options (skip cache, force enhancement, etc.).     * @return tiered OCR result (HIGH/MEDIUM/LOW/REJECT).     */    suspend fun recognize(        imageBytes: ByteArray,        options: OcrOptions = OcrOptions.DEFAULT,    ): TieredOcrResult = withContext(dispatcher) {        val startTime = System.currentTimeMillis()        val imageHash = computeSha256(imageBytes)        Timber.tag(TAG).i("OCR start: ${imageBytes.size} bytes, hash=${imageHash.take(16)}..., options=$options")        // 1. Cache lookup (skip if options.skipCache).        if (!options.skipCache) {            val cached = cache.get(imageHash)            if (cached != null) {                Timber.tag(TAG).d("OCR cache HIT (hash=${imageHash.take(16)}).")                return@withContext tieredOcrResult(cached.copy(                    processingTimeMs = System.currentTimeMillis() - startTime,                ))            }        }        // 2. Decide whether to apply enhancement.        val shouldEnhance = options.forceEnhancement || when (options.enhancementMode) {            EnhancementMode.ALWAYS -> true            EnhancementMode.NEVER -> false            EnhancementMode.AUTO -> {                // Auto-detect shadows — only enhance if needed.                enhancementPipeline.detectShadows(imageBytes)            }        }        // 3. Run enhancement (if applicable).        val enhancedImage: EnhancedImage?        val imageToOcr: ByteArray        if (shouldEnhance) {            val enhancementOptions = when (options.enhancementMode) {                EnhancementMode.AUTO, EnhancementMode.ALWAYS -> EnhancementOptions.DEFAULT                // AGGRESSIVE mode for very low-light (user-set)                else -> EnhancementOptions.DEFAULT            }            val enhanced = enhancementPipeline.enhance(imageBytes, enhancementOptions)            if (enhanced.isUsable && enhanced.value != null) {                enhancedImage = enhanced.value                // For ML Kit, we use the binary image (best for text recognition).                imageToOcr = enhancedImage.binaryImage.pixels                Timber.tag(TAG).d("Enhancement applied (${enhancedImage.processingTimeMs}ms).")            } else {                Timber.tag(TAG).w("Enhancement failed — falling back to raw image.")                enhancedImage = null                imageToOcr = imageBytes            }        } else {            enhancedImage = null            imageToOcr = imageBytes        }        // 4. Run ML Kit text recognition (with retry on failure).        val recognition = try {            recognizer.recognize(imageToOcr, enhancedImage != null)        } catch (t: Throwable) {            Timber.tag(TAG).e("ML Kit OCR failed (first attempt)", t)            // Retry: try on raw image (no enhancement).            if (enhancedImage != null) {                Timber.tag(TAG).w("Retrying OCR on raw image (no enhancement).")                try {                    recognizer.recognize(imageBytes, false)                } catch (t2: Throwable) {                    Timber.tag(TAG).e("ML Kit OCR retry also failed", t2)                    return@withContext ConfidenceTieredResult.rejected<OcrResult>(0.0f)                }            } else {                return@withContext ConfidenceTieredResult.rejected<OcrResult>(0.0f)            }        }        if (recognition.blocks.isEmpty()) {            Timber.tag(TAG).w("OCR produced no text blocks.")            val elapsedMs = System.currentTimeMillis() - startTime            val emptyResult = OcrResult(                fullText = "",                blocks = emptyList(),                extractedFields = emptyList(),                detectedDocumentType = DocumentType.UNKNOWN,                structuredDocument = null,                enhancementApplied = enhancedImage != null,                sourceImageHash = imageHash,                processingTimeMs = elapsedMs,                overallConfidence = 0.0f,            )            return@withContext tieredOcrResult(emptyResult)        }        // 5. Build full text + compute overall confidence.        val fullText = recognition.blocks.joinToString("\n") { it.text }        val overallConfidence = computeOverallConfidence(recognition.blocks)        // 6. Extract structured fields (regex).        val extractedFields = fieldExtractor.extract(fullText)        // 7. Detect document type.        val documentType = documentFormatDetector.detect(fullText, extractedFields)        // 8. Parse structured document.        val structuredDoc = structuredDocParser.parse(documentType, fullText, extractedFields, recognition.blocks)        val elapsedMs = System.currentTimeMillis() - startTime        val result = OcrResult(            fullText = fullText,            blocks = recognition.blocks,            extractedFields = extractedFields,            detectedDocumentType = documentType,            structuredDocument = structuredDoc,            enhancementApplied = enhancedImage != null,            sourceImageHash = imageHash,            processingTimeMs = elapsedMs,            overallConfidence = overallConfidence,        )        Timber.tag(TAG).i("OCR complete: ${recognition.blocks.size} blocks, ${extractedFields.size} fields, " +            "type=$documentType, confidence=$overallConfidence, ${elapsedMs}ms")        // 9. Cache the result (if not skipped).        if (!options.skipCache) {            cache.put(imageHash, result)        }        tieredOcrResult(result)    }    /**     * Compute the overall OCR confidence as a length-weighted average of block confidences.     *     * Longer text blocks contribute more to the overall score (they're more reliable).     */    private fun computeOverallConfidence(blocks: List<OcrBlock>): Float {        if (blocks.isEmpty()) return 0.0f        var totalWeight = 0.0        var weightedSum = 0.0        for (block in blocks) {            val weight = block.text.length.toDouble()            weightedSum += block.confidence * weight            totalWeight += weight        }        return if (totalWeight > 0) (weightedSum / totalWeight).toFloat() else 0.0f    }    /**     * Compute SHA-256 of the image bytes (cache key).     *     * The hash is also stored in [OcrResult.sourceImageHash] — but the image     * bytes themselves are NEVER persisted (privacy).     */    private fun computeSha256(imageBytes: ByteArray): String {        val digest = MessageDigest.getInstance("SHA-256")        return digest.digest(imageBytes).joinToString("") { "%02x".format(it) }    }    /**     * Clear the OCR cache (called by Settings → Privacy → Clear OCR Cache).     */    suspend fun clearCache(): Int = withContext(dispatcher) {        val count = cache.size()        cache.clear()        Timber.tag(TAG).i("OCR cache cleared ($count entries).")        count    }    /**     * Get OCR cache stats (for Settings → Storage UI).     */    fun cacheStats(): OcrCacheStats = cache.stats()    private companion object {        private const val TAG = "OcrEngine"    }}// ──────────────────────────────────────────────────────────────────────────/** OCR options. */data class OcrOptions(    val skipCache: Boolean = false,    val forceEnhancement: Boolean = false,    val enhancementMode: EnhancementMode = EnhancementMode.AUTO,) {    companion object {        /** Default — auto-detect shadows, use cache, normal enhancement. */        val DEFAULT = OcrOptions()        /** Fast — skip cache + skip enhancement (for clean scans). */        val FAST = OcrOptions(enhancementMode = EnhancementMode.NEVER)    }}/** When to apply image enhancement. */enum class EnhancementMode {    /** Auto-detect shadows — only enhance if needed (default). */    AUTO,    /** Always enhance (force). */    ALWAYS,    /** Never enhance (skip — for clean scans where speed matters). */    NEVER,}// ──────────────────────────────────────────────────────────────────────────/** Result of [OcrRecognizer.recognize]. */data class OcrRecognitionResult(    val blocks: List<OcrBlock>,    val recognizedLanguages: Set<String>,)// ──────────────────────────────────────────────────────────────────────────/** * OCR recognizer interface — abstracts ML Kit for testability. * * Production: [MlKitOcrRecognizer] wraps `com.google.mlkit:text-recognition`. * Tests: [FakeOcrRecognizer] returns canned OCR output. */interface OcrRecognizer {    /**     * Recognize text in [imageData].     *     * @param imageData the image data (raw bytes if not enhanced, or     *                  GrayscaleImage.pixels if enhanced).     * @param isEnhanced true if the image has been preprocessed (binarized).     * @return the recognition result.     */    suspend fun recognize(imageData: ByteArray, isEnhanced: Boolean): OcrRecognitionResult    /** True if the recognizer is ready (ML Kit model loaded). */    fun isReady(): Boolean    /** Get the set of supported script languages (e.g., "en", "hi", "ta"). */    fun supportedScripts(): Set<String>}/** * Document format detector — determines document type from OCR text. * * Uses heuristics (keyword matching) to classify the document as * Receipt, Prescription, BusinessCard, Invoice, AadhaarCard, PanCard, * HandwrittenNote, or Unknown. */class DocumentFormatDetector {    fun detect(fullText: String, extractedFields: List<OcrField>): DocumentType {        val text = fullText.lowercase()        return when {            text.contains("total") && (text.contains("₹") || text.contains("gst")) -> DocumentType.RECEIPT            text.contains("rx") || text.contains("dr.") || text.contains("tablet") -> DocumentType.PRESCRIPTION            text.contains("invoice") || text.contains("gstin") -> DocumentType.INVOICE            text.contains("\\d{12}".toRegex()) && text.contains("aadhaar") -> DocumentType.AADHAAR_CARD            text.contains("[a-z]{5}[0-9]{4}[a-z]".toRegex()) -> DocumentType.PAN_CARD            extractedFields.any { it.value.contains("phone", ignoreCase = true) } && extractedFields.any { it.value.contains("email", ignoreCase = true) } -> DocumentType.BUSINESS_CARD            else -> DocumentType.UNKNOWN        }    }}/** * Unified structured document parser — dispatches to the correct parser * based on detected document type. */class StructuredDocumentParser(    private val receiptParser: com.roshan.persona.vision.document.ReceiptParser,    private val prescriptionScanner: PrescriptionScanner,    private val businessCardParser: com.roshan.persona.vision.document.BusinessCardParser,    private val governmentIdParser: com.roshan.persona.vision.document.GovernmentIdParser,    private val invoiceParser: com.roshan.persona.vision.document.InvoiceParser,    private val handwrittenNoteParser: com.roshan.persona.vision.document.HandwrittenNoteParser,) {    fun parse(        documentType: DocumentType,        fullText: String,        extractedFields: List<OcrField>,        blocks: List<OcrBlock>,    ): StructuredDocument? {        return when (documentType) {            DocumentType.RECEIPT -> receiptParser.parse(fullText, extractedFields)            DocumentType.PRESCRIPTION -> prescriptionScanner.parse(fullText, extractedFields, blocks)            DocumentType.BUSINESS_CARD -> businessCardParser.parse(fullText, extractedFields)            DocumentType.INVOICE -> invoiceParser.parse(fullText, extractedFields)            DocumentType.AADHAAR_CARD -> governmentIdParser.parseAadhaar(fullText, extractedFields)            DocumentType.PAN_CARD -> governmentIdParser.parsePan(fullText, extractedFields)            DocumentType.HANDWRITTEN_NOTE -> handwrittenNoteParser.parse(fullText, blocks)            DocumentType.PRINTED_DOCUMENT, DocumentType.BARCODE, DocumentType.UNKNOWN -> null        }    }}
